import{_ as o,C as t,o as n,c as s,E as r,a2 as c}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/last-check-boundary-20260907/01-executor-comparison.en.png",v=JSON.parse('{"title":"The Request Said “Do Not Overwrite.” Why Was the File Replaced?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Request Said “Do Not Overwrite.” Why Was the File Replaced?","date":"2026-09-07","published_date":"2026-09-07","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","summary":"With the same no-overwrite flag, writing refused an existing destination while copying and moving replaced it. A controlled study separates recording a restriction, binding it to approval, and enforcing it.","cover":"/assets/last-check-boundary-20260907/01-no-overwrite-cover-v3.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled study complete; public-ingress applicability requires review; no fix implemented","pageClass":"last-check-boundary-article"},"headers":[],"relativePath":"en/engineering/2026-09-07-no-overwrite-executor-contract.md","filePath":"en/engineering/2026-09-07-no-overwrite-executor-contract.md","lastUpdated":1788773549000}'),d={name:"en/engineering/2026-09-07-no-overwrite-executor-contract.md"};function h(p,e,u,f,g,m){const a=t("ArticleCover"),i=t("ArticleTableScroll");return n(),s("div",null,[r(a,{image:"/assets/last-check-boundary-20260907/01-no-overwrite-cover-v3.png",kicker:"Open-source Engineering · Controlled Study",title:"The Request Said “Do Not Overwrite.” Why Was the File Replaced?",summary:"With the same no-overwrite flag, writing refused an existing destination while copying and moving replaced it. A controlled study separates recording a restriction, binding it to approval, and enforcing it.",version:"2026-09-07",languageHref:"/zh/engineering/2026-09-07-no-overwrite-executor-contract",languageLabel:"中文"}),r(i,{language:"en"}),e[0]||(e[0]=c('<p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/01-no-overwrite-cover-v3.png" target="_blank" rel="noreferrer">Open full-resolution cover</a></p><h1 id="the-request-said-do-not-overwrite-why-was-the-file-replaced" tabindex="-1">The Request Said “Do Not Overwrite.” Why Was the File Replaced? <a class="header-anchor" href="#the-request-said-do-not-overwrite-why-was-the-file-replaced" aria-label="Permalink to &quot;The Request Said “Do Not Overwrite.” Why Was the File Replaced?&quot;">​</a></h1><p>We put a no-overwrite restriction into a file-operation request. The approval record preserved it.</p><p>The destination was replaced anyway.</p><p>This was a controlled experiment with synthetic files, not a customer data-loss incident. The useful surprise was the comparison: with <code>overwrite=false</code>, writing refused an existing destination, but copying and moving succeeded and replaced its contents.</p><p>The approval record alone suggested that the restriction was explicit. The completion receipt alone suggested that the operation worked. Only when we compared both with the resulting bytes did the question become unavoidable: <strong>which component actually enforced “do not overwrite”?</strong></p><h2 id="_1-following-a-parameter-all-the-way-to-the-file" tabindex="-1">1. Following a parameter all the way to the file <a class="header-anchor" href="#_1-following-a-parameter-all-the-way-to-the-file" aria-label="Permalink to &quot;1. Following a parameter all the way to the file&quot;">​</a></h2><p>CodeFlowMu is a local multi-agent collaboration system we are developing. It organizes work through task files, execution sessions, and evidence. Its controlled workspace operations construct a concrete request, obtain one-time approval, check the request at execution, and delegate to a filesystem executor.</p><p>Our question was not whether approval could be bypassed. It was whether a restriction already inside the approval chain retained its meaning at the final operation.</p><p>The experiment used the real request builder, approval service, and filesystem executor. Each scenario created synthetic files in a fresh isolated directory and received a research-only administrative approval through the service. We did not invoke the live panel or let an agent touch business files.</p><p>At source commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>, we ran four scenarios twice:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Restriction</th><th>Result, identical in both rounds</th><th>Filesystem observation</th></tr></thead><tbody><tr><td>Write to an absent destination</td><td>No overwrite</td><td>Succeeded</td><td>New contents written</td></tr><tr><td>Write to an existing destination</td><td>No overwrite</td><td>Refused; operation recorded as failed</td><td>Original contents preserved</td></tr><tr><td>Copy to an existing destination</td><td>No overwrite</td><td>Succeeded</td><td>Destination replaced; source retained</td></tr><tr><td>Move to an existing destination</td><td>No overwrite</td><td>Succeeded</td><td>Destination replaced; source moved</td></tr></tbody></table><p>The second row is essential. The write executor already has a working protection; the copy and move results do not justify saying that every file operation ignores overwrite constraints. The first row matters too: refusing more operations is not inherently correct. A legitimate new file should still be created.</p><p>These eight observations establish a difference between tested interfaces, not a production incident rate.</p><p><img src="'+l+'" alt="Observed write, copy and move outcomes with the same no-overwrite flag"></p><p><em>Figure 1. Explanatory rendering of E0–E3, two rounds each, retaining both the legitimate-creation and refusal controls. This is not an experiment screenshot; Source: formal controlled-study records; see the <a href="/joinwell52/en/research/evidence/2026-09-07-last-check-effect-boundary">evidence notes</a>.</em></p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/01-executor-comparison.en.png" target="_blank" rel="noreferrer">Open full-resolution figure</a></p><h2 id="_2-the-restriction-survived-its-enforcement-did-not-follow-every-branch" tabindex="-1">2. The restriction survived. Its enforcement did not follow every branch <a class="header-anchor" href="#_2-the-restriction-survived-its-enforcement-did-not-follow-every-branch" aria-label="Permalink to &quot;2. The restriction survived. Its enforcement did not follow every branch&quot;">​</a></h2><p>We traced the parameter through the code. The shared workspace input includes <code>overwrite</code>; the builder puts it in the approval request, and reconstruction from the approval record preserves it. Both copy and move records retained <code>false</code>.</p><p>The result was therefore not caused by a model omitting the flag, or by transmission turning false into true.</p><p>The difference appears in the final executor:</p><ul><li>The write branch checks whether the destination exists and overwrite is explicitly forbidden. It raises <code>target_exists_and_overwrite_is_false</code> and preserves the bytes.</li><li>The copy branch calls the file-copy operation without using that flag in the branch.</li><li>The move branch calls the rename operation without using it either.</li></ul><p>On the tested Windows system, the latter two operations replaced the destination. We read the actual result; this is not an inference based only on function names.</p><p>An approval digest can establish that an execution request matches its approved representation. It cannot, by itself, establish that the executor implements every restriction in that representation. A faithfully stored field does not enforce itself.</p><p>We also distinguished callback entry from operation outcome. The refused write entered the callback, then its exception was recorded as a failed operation. Copy and move were recorded as successful. A research process exiting normally is not proof that every product contract passed acceptance.</p><h2 id="_3-a-create-file-proposal-raises-a-related-question" tabindex="-1">3. A “create file” proposal raises a related question <a class="header-anchor" href="#_3-a-create-file-proposal-raises-a-related-question" aria-label="Permalink to &quot;3. A “create file” proposal raises a related question&quot;">​</a></h2><p>OpenAI Agents SDK is a library for building agent applications. In its still-open <a href="https://github.com/openai/openai-agents-python/pull/4893" target="_blank" rel="noreferrer">PR #4893</a>, an author reports a create operation replacing an existing file and proposes an absence check. We did not independently rerun that work.</p><p>That restriction comes from the operation’s definition; ours comes from an explicit request parameter. Both ask whether the effect promised to the caller is enforced where the file changes. Neither implies that all write operations should become create-only.</p><p>A separate, also-open <a href="https://github.com/openai/openai-agents-python/pull/4894" target="_blank" rel="noreferrer">PR #4894</a> addresses delimiters inside mount-option inputs. It is a reminder that validating a permission and preserving a parameter’s meaning are separate responsibilities.</p><p>External cases illuminate the question. They neither reproduce our result nor prove that our product shares their complete failure paths.</p><h2 id="_4-fix-the-executor—or-first-narrow-the-interface" tabindex="-1">4. Fix the executor—or first narrow the interface? <a class="header-anchor" href="#_4-fix-the-executor—or-first-narrow-the-interface" aria-label="Permalink to &quot;4. Fix the executor—or first narrow the interface?&quot;">​</a></h2><p>The tempting next step is to add a condition. Before choosing that implementation, we need to settle the contract: <strong>which operations is no-overwrite supposed to constrain?</strong></p><p>If the product contract applies it to write, copy, and move, the latter branches need to enforce it with an appropriate filesystem operation. If the guarantee must also hold under concurrency, sequential checks are insufficient evidence; the interval between checking and writing needs its own tests.</p><p>If the flag is write-only, copy and move should reject it as inapplicable, or use input types that prevent the ambiguity. Silently accepting it into an approval record invites callers to rely on a restriction that does nothing.</p><p>We confirmed reproducible behavior at the internal controlled-request boundary. Static inspection also found the executor registrations wired to the shared preparation and execution functions. We have not completed the public-ingress investigation: which callers can pass the flag, how the interface presents it, and whether it is formally specified as a shared restriction.</p><p>This warrants a narrow contract review. It is not a demonstrated live privilege bypass, and no fix has been implemented. The study did not change product code or authorize a new general-purpose permission framework.</p><h2 id="_5-test-how-restrictions-fail-not-just-whether-approval-succeeds" tabindex="-1">5. Test how restrictions fail, not just whether approval succeeds <a class="header-anchor" href="#_5-test-how-restrictions-fail-not-just-whether-approval-succeeds" aria-label="Permalink to &quot;5. Test how restrictions fail, not just whether approval succeeds&quot;">​</a></h2><p>For each important restriction, record where it enters, where approval binds it, which executor branches consume it, what rejection looks like, and whether the original object remains unchanged.</p><p>Tests should come in pairs: a legitimate case that completes, and a prohibited case that is refused without producing the forbidden effect. Checking only an error string can miss another false protection: modifying the file first and reporting an error afterward.</p><p>Test each operation mode separately. A positive write test does not cover copy and move. Shared input types do not establish shared enforcement.</p><p><strong>Recording a restriction creates an audit trail. Enforcing it creates the capability a caller can actually rely on.</strong></p><h2 id="evidence-and-limits" tabindex="-1">Evidence and limits <a class="header-anchor" href="#evidence-and-limits" aria-label="Permalink to &quot;Evidence and limits&quot;">​</a></h2><p>This article uses E0–E3, twice each, from the formal dataset. The companion article uses different rows from the same research batch. The <a href="/joinwell52/en/research/evidence/2026-09-07-last-check-effect-boundary">English evidence guide</a>, <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/observations.json" target="_blank" rel="noreferrer">de-identified observations</a>, and <a href="/joinwell52/zh/research/evidence/2026-09-07-last-check-effect-boundary">Chinese guide</a> are publicly provided with this article.</p><p>All files were synthetic and isolated. There is no production loss-rate sample, live HTTP/panel/agent end-to-end test, or multi-process overwrite-race test. Findings are bounded by the pinned source and Windows environment. Record-integrity checks are not product reruns or independent QA. No repair, merge, or release is claimed.</p>',44))])}const b=o(d,[["render",h]]);export{v as __pageData,b as default};
